-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Tests > - Testprozess > - Testfallerstellung

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Testfälle in der testgetriebenen Entwicklung (TDD) vor der Implementierung des Codes erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "TDD verlangt Tests zuerst"}, {"text": "Nein", "correct": false, "because": "Test-vor-Code ist Kernprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Testfälle in TDD ohne Kenntnis der Anforderungen sinnvoll erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen definieren Testziele"}, {"text": "Ja", "correct": false, "because": "Ohne Anforderungen fehlt Basis"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, dass ein Testfall in TDD zunächst fehlschlägt?', 2, '[{"text": "Ja", "correct": true, "because": "Fehlschlag ist Teil des TDD-Zyklus"}, {"text": "Nein", "correct": false, "because": "Rot-Grün-Refaktor erfordert Fehlschlag"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Testfallerstellung in TDD ohne Berücksichtigung von Randfällen vollständig sein?', 2, '[{"text": "Nein", "correct": true, "because": "Randfälle sind für Qualität entscheidend"}, {"text": "Ja", "correct": false, "because": "Unvollständig ohne Randfälle"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Testfälle in TDD immer auf einzelne Funktionen beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Tests können auch Integration abdecken"}, {"text": "Ja", "correct": false, "because": "Flexibilität in Testgranularität"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Testfallerstellung im TDD-Prozess?', 2, '[{"text": "Sie definiert die Anforderungen vor der Implementierung", "correct": true, "because": "Tests als Spezifikation"}, {"text": "Sie überprüft den Code nach Fertigstellung", "correct": false, "because": "Tests kommen zuerst"}, {"text": "Sie optimiert die Laufzeit", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt folgt unmittelbar auf die Erstellung eines Testfalls in TDD?', 3, '[{"text": "Test ausführen und fehlschlagen lassen", "correct": true, "because": "Rot-Phase im TDD-Zyklus"}, {"text": "Code implementieren", "correct": false, "because": "Nach Fehlschlag"}, {"text": "Test dokumentieren", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Testfallerstellung in TDD am wichtigsten?', 2, '[{"text": "Klarheit der Anforderung", "correct": true, "because": "Tests spiegeln Anforderungen"}, {"text": "Komplexität des Codes", "correct": false, "because": "Code kommt später"}, {"text": "Laufzeitoptimierung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Testfall wird in TDD typischerweise zuerst erstellt?', 2, '[{"text": "Unit-Test", "correct": true, "because": "Fokus auf kleine Einheiten"}, {"text": "Integrationstest", "correct": false, "because": "Spätere Phase"}, {"text": "Systemtest", "correct": false, "because": "Gesamtsystem später"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Testfallerstellung in TDD?', 2, '[{"text": "Spezifikation des erwarteten Verhaltens", "correct": true, "because": "Tests als Anleitung"}, {"text": "Fehlerbehebung im bestehenden Code", "correct": false, "because": "Nicht primär"}, {"text": "Vermeidung von Dokumentation", "correct": false, "because": "Tests sind Dokumentation"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien leiten die Testfallerstellung in TDD?', 4, '[{"text": "Tests vor Code", "correct": true, "because": "Kernprinzip von TDD"}, {"text": "Einfachheit", "correct": true, "because": "Tests klar und fokussiert"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Automatisierung zentral"}, {"text": "Anforderungsgetrieben", "correct": true, "because": "Tests spiegeln Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sollten in einem Testfall für TDD enthalten sein?', 3, '[{"text": "Eingabedaten", "correct": true, "because": "Definiert Testbedingungen"}, {"text": "Erwartetes Ergebnis", "correct": true, "because": "Überprüft Verhalten"}, {"text": "Implementierungsdetails", "correct": false, "because": "Nicht relevant"}, {"text": "Testbedingungen", "correct": true, "because": "Spezifiziert Szenario"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Testfällen werden in TDD typischerweise erstellt?', 3, '[{"text": "Unit-Tests", "correct": true, "because": "Kleine Einheiten testen"}, {"text": "Akzeptanztests", "correct": true, "because": "Anforderungen abdecken"}, {"text": "Performancetests", "correct": false, "because": "Spätere Optimierung"}, {"text": "Regressionstests", "correct": true, "because": "Sichern bestehende Funktionalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Testfallerstellung in TDD?', 4, '[{"text": "Klarheit über Anforderungen", "correct": true, "because": "Tests als Spezifikation"}, {"text": "Frühe Fehlererkennung", "correct": true, "because": "Fehlschläge sofort sichtbar"}, {"text": "Höhere Entwicklungskosten", "correct": false, "because": "Kosten eher gesenkt"}, {"text": "Bessere Codequalität", "correct": true, "because": "Tests fördern Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Testfallerstellung in TDD auftreten?', 3, '[{"text": "Hoher initialer Aufwand", "correct": true, "because": "Tests vorab schreiben"}, {"text": "Unklare Anforderungen", "correct": true, "because": "Schwierig ohne Klarheit"}, {"text": "Langsame Ausführung", "correct": false, "because": "Tests meist schnell"}, {"text": "Komplexität bei Randfällen", "correct": true, "because": "Erfordert Sorgfalt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Testfälle in TDD müssen vor der Implementierung erstellt werden. b) TDD erfordert keine Anforderungsanalyse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests zuerst, Anforderungen nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testfälle in TDD sollten zunächst fehlschlagen. b) Testfallerstellung ist in TDD optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlschlag zentral, Erstellung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) TDD-Testfälle decken nur Unit-Tests ab. b) Testfälle in TDD dienen als Dokumentation.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Tests vielfältig, dokumentieren"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Testfallerstellung in TDD erfordert detaillierte Implementierungskenntnisse. b) Randfälle sind in TDD-Testfällen wichtig.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Implementierung folgt, Randfälle entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) TDD-Testfälle können die Entwicklung beschleunigen. b) Testfälle in TDD müssen manuell ausgeführt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests leiten, Automatisierung üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

